        en_dump(&mut d.et, &mut d.gl, &mut d.wd, &mut d.ln, &mut d.mk, &mut d.fnt, &mut d.grl, &mut d.gfl, &mut s.ggp, &mut s.grg, ev, &mut d.evidence);
        ev_emit_ofuse(&mut d.evidence, 0, 1, &mut ev.ofuse);
